      vec3 cw = metal;
      cw = mix(cw, vec3(0.957, 0.396, 0.941), clamp(glow * 0.35 + lip * 0.45, 0.0, 1.0));
      cw = mix(cw, mix(vec3(0.196, 0.004, 0.145), vec3(0.35, 0.05, 0.3), smoothstep(-0.1, 0.0, dS)), hole);
      pc = mix(pc, cw, wC);
